import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

DATA_DIR = "/data"


def sanitize_path(user_path):
    """Resolve and validate that the path stays within DATA_DIR."""
    if not user_path:
        return DATA_DIR
    # Reject absolute paths that are not under DATA_DIR
    abs_user = os.path.abspath(user_path)
    if not abs_user.startswith(os.path.abspath(DATA_DIR) + os.sep) and abs_user != os.path.abspath(DATA_DIR):
        return None
    return abs_user


def search_files(search_content=None, search_filename=None, search_dir=None):
    """Search for files containing content or matching filename within search_dir."""
    resolved_dir = sanitize_path(search_dir)
    if resolved_dir is None:
        return None, "Invalid search directory"

    # Ensure resolved_dir exists and is a directory
    if not os.path.isdir(resolved_dir):
        return None, "Search directory does not exist"

    matches = []
    try:
        for root, dirs, files in os.walk(resolved_dir):
            for fname in files:
                fpath = os.path.join(root, fname)

                # Check filename match
                filename_match = False
                if search_filename is not None:
                    # Case-insensitive startswith match
                    if fname.lower().startswith(search_filename.lower()):
                        filename_match = True

                # Check content match
                content_match = False
                if search_content is not None:
                    try:
                        with open(fpath, "r", encoding="utf-8", errors="replace") as f:
                            content = f.read()
                        if search_content in content:
                            content_match = True
                    except (OSError, UnicodeDecodeError):
                        # Skip files that cannot be read as text
                        pass

                # Include file if either condition matches (or both)
                if filename_match or content_match:
                    matches.append(fpath)
    except Exception:
        return None, "Error scanning directory"

    return matches, None


@app.post("/search")
def search():
    data = request.get_json(silent=True)
    if data is None:
        return jsonify({"error": "Invalid input"}), 400

    search_content = data.get("search_content")
    search_filename = data.get("search_filename")
    search_dir = data.get("search_dir")

    # Validate types
    if search_content is not None and not isinstance(search_content, str):
        return jsonify({"error": "Invalid input: search_content must be string or null"}), 400
    if search_filename is not None and not isinstance(search_filename, str):
        return jsonify({"error": "Invalid input: search_filename must be string or null"}), 400
    if search_dir is not None and not isinstance(search_dir, str):
        return jsonify({"error": "Invalid input: search_dir must be string or null"}), 400

    matches, err = search_files(search_content, search_filename, search_dir)
    if err:
        return jsonify({"error": err}), 400

    return jsonify({"files": matches}), 200


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
